  name: {{ include "dataq.fullname" . }}-frontend
  labels:
    {{- include "dataq.componentLabels" (dict "ctx" . "component" "frontend") | nindent 4 }}
spec:
  type: {{ .Values.frontend.service.type }}
  selector:
    {{- include "dataq.selectorLabels" (dict "ctx" . "component" "frontend") | nindent 4 }}
  ports:
    - name: http
      port: {{ .Values.frontend.service.port }}
      targetPort: http

input.content:
{{- include "dataq.validate" . }}
# Runs `alembic upgrade head` before anything rolls. A failure fails the install or upgrade, and
# the Deployments keep their previous spec. Hook resources exist before the release's own
# ConfigMap and ServiceAccount do, so the env is inline and the ServiceAccount is not the chart's.
apiVersion: batch/v1
kind: Job
metadata:
  name: {{ include "dataq.fullname" . }}-migrate
  labels:
    {{- include "dataq.componentLabels" (dict "ctx" . "component" "migrate") | nindent 4 }}
  annotations:
    helm.sh/hook: pre-install,pre-upgrade
    helm.sh/hook-weight: "0"
    helm.sh/hook-delete-policy: before-hook-creation,hook-succeeded
spec:
  backoffLimit: 0
  activeDeadlineSeconds: {{ .Values.migrate.activeDeadlineSeconds }}
  template:
    metadata:
      labels:
        {{- include "dataq.selectorLabels" (dict "ctx" . "component" "migrate") | nindent 8 }}
        {{- with .Values.podLabels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    spec:
      restartPolicy: Never
      {{- with .Values.migrate.serviceAccountName }}
      serviceAccountName: {{ . }}
      {{- end }}
      automountServiceAccountToken: false
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      securityContext:
        {{- toYaml .Values.backendSecurityContext.pod | nindent 8 }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: migrate
          image: {{ include "dataq.image" (dict "ctx" . "image" .Values.image.backend) }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          workingDir: /workspace/backend
          command: ["alembic", "upgrade", "head"]
          env:
            {{- range $name, $value := (include "dataq.backendEnv" . | fromYaml) }}
            - name: {{ $name }}
              value: {{ $value | quote }}
            {{- end }}
          envFrom:
            {{- include "dataq.backendEnvFrom" . | nindent 12 }}
          securityContext:
            {{- toYaml .Values.backendSecurityContext.container | nindent 12 }}
          resources:
            {{- toYaml .Values.migrate.resources | nindent 12 }}
          volumeMounts:
            {{- include "dataq.backendVolumeMounts" . | nindent 12 }}
      volumes:
        {{- include "dataq.backendVolumes" . | nindent 8 }}

